const body = $json.body ?? {};

return { json: {
  topic: body.topic,
  origin_session_id: body.chatSessionId || null,
  trigger_source: body.triggerSource || 'chat',
  status: 'running',
  latest_status: 'Researching',
} };

const output = $json.output || '';
const idx = output.indexOf('SOURCES:');
let urls = [];
let findings = output;
if (idx !== -1) {
  const block = output.slice(idx + 'SOURCES:'.length);
  urls = block.match(/https?:\/\/[^\s)\]]+/g) || [];
  findings = output.slice(0, idx);
}
urls = [...new Set(urls)];
return [{ json: { findings: findings.trim(), sourceUrls: urls } }];

