let parsed;
try {
  parsed = JSON.parse($json.message?.content ?? '{}');
} catch (e) {
  parsed = {};
}
return [{ json: { title: parsed.title || '', markdown: parsed.markdown || '' } }];

const documentId = $('Insert Document Row').item.json.id;
const markdown = $('Parse Synthesis').item.json.markdown || '';
const lines = markdown.split('\n');
const sections = [];
let current = { heading: null, lines: [] };
for (const line of lines) {
  if (/^#{1,6}\s+.+/.test(line)) {
    if (current.lines.length) sections.push(current);
    current = { heading: line.replace(/^#{1,6}\s+/, '').trim(), lines: [] };
  } else {
    current.lines.push(line);
  }
}
if (current.lines.length) sections.push(current);

const TARGET_SIZE = 1000;
const chunks = [];
for (const section of sections) {
  const text = section.lines.join('\n').trim();
  if (!text) continue;
  if (text.length <= TARGET_SIZE * 1.2) {
    chunks.push({ heading: section.heading, content: text });
    continue;
  }
  const paragraphs = text.split(/\n\s*\n/);
  let buf = '';
  for (const p of paragraphs) {
    if (buf && (buf.length + p.length) > TARGET_SIZE) {
      chunks.push({ heading: section.heading, content: buf.trim() });
      buf = p;
    } else {
      buf = buf ? buf + '\n\n' + p : p;
    }
  }
  if (buf.trim()) chunks.push({ heading: section.heading, content: buf.trim() });
}

if (chunks.length === 0) chunks.push({ heading: null, content: markdown.trim() || $('Prepare Document Row').item.json.topic });

return chunks.map((c, i) => ({ json: { documentId, chunkIndex: i, heading: c.heading, content: c.content } }));

const originSessionId = $('Prepare Document Row').item.json.origin_session_id;
const topic = $('Prepare Document Row').item.json.topic;
const title = $('Parse Synthesis').item.json.title || topic;
const summary = 'Finished researching "' + topic + '". Saved as "' + title + '" - ask me about it any time.';
return [{ json: { origin_session_id: originSessionId, summary } }];

const rows = $input.all().map((i) => i.json).filter((r) => r.id !== undefined);
if (rows.length === 0) {
  return [{ json: { found: false } }];
}
const row = rows[0];
return [{ json: {
  found: true,
  status: row.status,
  latestStatus: row.latest_status,
  title: row.title || undefined,
  topic: row.topic,
} }];

const rows = $input.all().map((i) => i.json).filter((r) => r.content !== undefined);
const results = rows.map((r) => ({
  content: r.content,
  heading: r.heading || undefined,
  similarity: r.similarity,
  document: {
    title: r.title,
    topic: r.topic,
    sourceUrls: (typeof r.source_urls === 'string') ? JSON.parse(r.source_urls) : (r.source_urls || []),
  },
}));
return [{ json: { results } }];
